// src/main.ts — prints the closing time of the lab.
// Node runs .ts files directly, so import the file that really exists: hello.ts.
import { formatTime } from './hello.ts';

// formatTime takes minutes since 00:00, not an "HH:MM" string: 21:00 is 21 * 60.
console.log('LabFlow closes at ' + formatTime(21 * 60));

// src/hello.ts — given, do not change.
export function formatTime(minutes: number): string {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

