// src/role.ts — LabFlow roles and the approval rule (BR-06: students need approval above 30 seats).
export enum Role {
  STUDENT = 'STUDENT',
  LECTURER = 'LECTURER',
  ADMIN = 'ADMIN',
}

export function needsApproval(seats: number, role: Role): boolean {
  if (role === Role.LECTURER || role === Role.ADMIN) return false;
  return seats > 30;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { needsApproval } from '../src/role.ts';

test('31 student seats need approval', () => assert.equal(needsApproval(31, 'STUDENT'), true));
test('30 student seats do not', () => assert.equal(needsApproval(30, 'STUDENT'), false));
test('lecturers never wait', () => assert.equal(needsApproval(200, 'LECTURER'), false));

import { needsApproval } from '../src/role.ts';

needsApproval(31, 'lecturer'); // expect TS2345
needsApproval(31, 'GUEST'); // expect TS2345

